    private void bt_salvarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_bt_salvarActionPerformed
        try {  
            String email = txt_email.getText();
            String senha = txt_senha.getText();
            String senhaConfirm = txt_senha_confirm.getText();
            String nome = txt_nome.getText();

            
            if (nome.trim().isEmpty()) {
                mostrarMensagem("O nome não pode estar vazio!");
                return;
            }

            if (!isEmailValido(email)) {
                mostrarMensagem("Email inválido!");
                return;
            }

            if (!isSenhaValida(senha, senhaConfirm)) {
                return; // add mensagem
            }
            

            // Registra user
            Cad c = new Cad();
            c.cadUser(nome,email, senha);
            
            // fecha janela
            F_Login l = new F_Login();
            this.dispose();
            l.setVisible(true);

        } catch (Exception e) {
            System.out.println("Erro: " + e.getMessage());
        }
    }//GEN-LAST:event_bt_salvarActionPerformed

