    private boolean isEmailValido(String email) {
        return email.matches("^[\\w-\\.]+@([\\w-]+\\.)+[\\w-]{2,4}$");
    }

    private boolean isSenhaValida(String senha, String senhaConfirm) {
        if (senha.length() < 6 || senhaConfirm.length() < 6) {
            mostrarMensagem("A senha deve ter mais 6 caracteres!");
            return false;
        }
        if (!senha.equals(senhaConfirm)) {
            mostrarMensagem("As senhas não coincidem!");
            return false;
        }
        return true;
    }

    private int isCertificacaoValida(int certificacao) {
        if (certificacao == 3){
            return 0;
        }else{
            return 1;
        }
    }
    
    private int isIntereces(int viagens, int musica, int gastronomia, int livros, int esportes, int natureza, int artes, int jogos, int animais, int causa) {
        int aux = 0;
        if (viagens == 1){
            aux++;
        }
        if (musica == 1){
            aux++;
        }
        if (gastronomia == 1){
            aux++;
        }
        if (livros== 1){
            aux++;
        }
        if (esportes == 1){
            aux++;
        }
        if (natureza == 1){
            aux++;
        }
        if (artes == 1){
            aux++;
        }
        if (jogos == 1){
            aux++;
        }
        if (animais == 1){
            aux++;
        }
        if (causa == 1){
            aux++;
        }
        if (aux >= 3){
            return 1;
        }else{
            return 0;
        }
    }

    private void mostrarMensagem(String mensagem) {
        JOptionPane.showMessageDialog(null, mensagem);
    }
